-- Migration 0001: the first table, `cameras`.
--
-- One row per public camera shown on the globe. This is a minimal starting
-- shape; sources, feed details, and search come in later migrations.
--
-- Coordinates are WGS 84 decimal degrees, the system GPS and Cesium use.
-- D1 is SQLite, which has no spatial index, so the globe looks cameras up by
-- latitude and longitude ranges using the index below.

CREATE TABLE cameras (
  -- Stable public identifier, a UUID generated by the app.
  id TEXT PRIMARY KEY NOT NULL,
  -- Display name, for example "Times Square, looking north".
  name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
  latitude REAL NOT NULL CHECK (latitude BETWEEN -90 AND 90),
  longitude REAL NOT NULL CHECK (longitude BETWEEN -180 AND 180),
  -- What the camera shows; used for the category filters.
  category TEXT NOT NULL
    CHECK (category IN ('city', 'nature', 'traffic', 'weather', 'landmark', 'beach', 'other')),
  -- `active` cameras appear on the globe; `hidden` ones are kept but not shown.
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'hidden')),
  -- ISO 8601 UTC timestamps, for example 2026-11-17T12:00:00Z.
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
);

-- Finds active cameras inside a latitude/longitude box.
CREATE INDEX cameras_status_location ON cameras (status, latitude, longitude);
